// Package testfixture は、テスト専用のサンプル鍵素材と
// エクスポートzipフィクスチャの生成ヘルパーを提供する。
// 本番コードからはimportしないこと。
package testfixture

import (
	"archive/zip"
	"encoding/json"
	"fmt"
	"os"

	"github.com/nsuiteio/nsuite-mpc-key-export/utility/errutil"
	"github.com/nsuiteio/nsuite-mpc-key-export/utility/secutil"
	"github.com/nsuiteio/nsuite-mpc-key-export/utility/strutil"
)

const (
	RSAPrivateKeyHex = ""

	KeySharesECDSAJSON = `[
		"",
		"",
		""
	]`
	SamplePrivateKeyECDSAHex = "0x9a474709c4b905434438ff9e5891234e0c028d80d376cf259fa7a1280cb43300"

	KeySharesEdDSAJSON = `[
		"",
		"",
		""
	]`
	SamplePrivateKeyEdDSAHex = "0x08314f94a480690ae6819cd3b8a8cd44938ea6f34f17d8b5929688087eb6c909"
)

// RSAPrivateKey はサンプルシェアの暗号化に対応する受取用キーペアを返す。
func RSAPrivateKey() (secutil.EncryptionPrivateKey, error) {
	prvBs, err := strutil.FromHex(RSAPrivateKeyHex)
	if err != nil {
		return nil, errutil.Wrap(err)
	}
	return secutil.EncryptionPrivateKeyFromBytes(prvBs)
}

// ShareHexes はサンプルシェア（gzip済みJSONのhex表現）を返す。
func ShareHexes() (ecdsaHexes, eddsaHexes []string, err error) {
	if err := json.Unmarshal(
		[]byte(KeySharesECDSAJSON), &ecdsaHexes,
	); err != nil {
		return nil, nil, errutil.Wrap(err)
	}
	if err := json.Unmarshal(
		[]byte(KeySharesEdDSAJSON), &eddsaHexes,
	); err != nil {
		return nil, nil, errutil.Wrap(err)
	}
	return ecdsaHexes, eddsaHexes, nil
}

// WriteKeyShareZip は、サンプルシェアをRSA公開鍵で暗号化した
// エクスポートzip（実運用と同形式: 3エントリのJSON）をpathへ書き出す。
func WriteKeyShareZip(path string) error {
	prv, err := RSAPrivateKey()
	if err != nil {
		return errutil.Wrap(err)
	}
	pub := prv.PublicKey()

	ecdsaHexes, eddsaHexes, err := ShareHexes()
	if err != nil {
		return errutil.Wrap(err)
	}

	file, err := os.Create(path)
	if err != nil {
		return errutil.Wrap(err)
	}

	zw := zip.NewWriter(file)
	for i := range ecdsaHexes {
		ecdsaBs, err := strutil.FromHex(ecdsaHexes[i])
		if err != nil {
			return errutil.Wrap(err)
		}
		eddsaBs, err := strutil.FromHex(eddsaHexes[i])
		if err != nil {
			return errutil.Wrap(err)
		}
		encECDSA, err := pub.Encrypt(ecdsaBs)
		if err != nil {
			return errutil.Wrap(err)
		}
		encEdDSA, err := pub.Encrypt(eddsaBs)
		if err != nil {
			return errutil.Wrap(err)
		}
		bs, err := json.Marshal(map[string][]byte{
			"ecdsa": encECDSA,
			"eddsa": encEdDSA,
		})
		if err != nil {
			return errutil.Wrap(err)
		}
		w, err := zw.Create(fmt.Sprintf("share-%d.json", i+1))
		if err != nil {
			return errutil.Wrap(err)
		}
		if _, err := w.Write(bs); err != nil {
			return errutil.Wrap(err)
		}
	}
	if err := zw.Close(); err != nil {
		return errutil.Wrap(err)
	}
	return errutil.Wrap(file.Close())
}
